\coordinate (A) at (-3.382,-0.149);
\coordinate (B) at (3.329,-0.149);
\coordinate (C) at (-1.697,2.759);
\coordinate (O) at (-0.026,-0.152);
\coordinate (P) at (0.987,-0.150);



\coordinate (D) at (2.876,1.533);


