  \fill (\v) circle (2.500pt);


\node[left]        at (A) {\fontsize{18}{21.6}\selectfont$A$};
\node[right]       at (B) {\fontsize{18}{21.6}\selectfont$B$};
\node[below]       at (O) {\fontsize{18}{21.6}\selectfont$O$};
\node[below]       at (P) {\fontsize{18}{21.6}\selectfont$P$};
\node[above left]  at (C) {\fontsize{18}{21.6}\selectfont$C$};
\node[above right] at (D) {\fontsize{18}{21.6}\selectfont$D$};
\end{tikzpicture}
\end{document}

